import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from kde ----
/** mulberry32, seeded so the sample is byte-identical on every reload. */
function createRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function createSample(count: number, seed: number): number[] {
  const random = createRandom(seed);
  const values: number[] = [];
  while (values.length < count) {
    const u = random() || Number.EPSILON; // Box-Muller diverges at exactly zero
    const normal = Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * random());
    const short = random() < 0.36;
    const value = short ? 54.2 + 5.5 * normal : 79.8 + 6.2 * normal;
    values.push(Math.round(value * 10) / 10);
  }
  return values;
}

/** Two well-separated modes, so an over-wide bandwidth visibly erases the gap between them. */
const eruptionWaits: number[] = createSample(432, 20260813);

const MARGIN = { top: 16, right: 20, bottom: 40, left: 48 };
const BAR_FILL = '#3d4145';
const BANDWIDTHS = [1.5, 4, 20];
const BIN_COUNT = 30;
const GRID_STEPS = 140;

/** Epanechnikov kernel: the minimum-variance choice, and what the notebook uses. */
function epanechnikov(bandwidth: number) {
  return (value: number) => {
    const u = value / bandwidth;
    return Math.abs(u) <= 1 ? (0.75 * (1 - u * u)) / bandwidth : 0;
  };
}

function estimateDensity(sample: number[], bandwidth: number, grid: number[]): number[] {
  const kernel = epanechnikov(bandwidth);
  return grid.map((t) => d3.mean(sample, (d) => kernel(t - d)) ?? 0);
}

/** The raw sample: one observation per value, in any order. */
export type Data = number[];

export default function KernelDensityEstimation({
  data = eruptionWaits,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.55);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const [lo, hi] = useMemo(
    () => d3.nice(...(d3.extent(data) as [number, number]), 10),
    [data]
  );

  const binWidth = (hi - lo) / BIN_COUNT;

  // Explicit uniform thresholds: d3.ticks would leave a ragged half-width bin at each end.
  const bins = useMemo(
    () =>
      d3
        .bin<number, number>()
        .domain([lo, hi])
        .thresholds(d3.range(1, BIN_COUNT).map((i) => lo + i * binWidth))(data),
    [data, lo, hi, binWidth]
  );

  const curves = useMemo(() => {
    const grid = d3.range(GRID_STEPS + 1).map((i) => lo + (i * (hi - lo)) / GRID_STEPS);
    return BANDWIDTHS.map((bandwidth) => ({
      bandwidth,
      // Density is per unit x; scaling by the bin width puts it on the histogram's proportion axis.
      points: estimateDensity(data, bandwidth, grid).map(
        (density, i): [number, number] => [grid[i], density * binWidth]
      )
    }));
  }, [data, lo, hi, binWidth]);

  const x = useMemo(() => d3.scaleLinear().domain([lo, hi]).range([0, innerWidth]), [lo, hi, innerWidth]);

  const y = useMemo(() => {
    const peakBin = (d3.max(bins, (b) => b.length) ?? 0) / data.length;
    const peakCurve = d3.max(curves, (c) => d3.max(c.points, (p) => p[1]) ?? 0) ?? 0;
    return d3.scaleLinear().domain([0, Math.max(peakBin, peakCurve)]).nice().range([innerHeight, 0]);
  }, [data, bins, curves, innerHeight]);

  const line = useMemo(
    () =>
      d3
        .line<[number, number]>()
        .curve(d3.curveBasis)
        .x((p) => x(p[0]))
        .y((p) => y(p[1])),
    [x, y]
  );

  const color = useMemo(() => d3.scaleOrdinal(BANDWIDTHS.map(String), d3.schemeObservable10), []);

  const xTicks: Tick[] = useMemo(
    () =>
      x.ticks(Math.max(3, Math.round(innerWidth / 70))).map((v) => ({
        value: String(v),
        offset: x(v)
      })),
    [x, innerWidth]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(5).map((v) => ({ value: d3.format('.0%')(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Histogram of times between eruptions with kernel density estimates at three bandwidths"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <text x={innerWidth} y={innerHeight + 34} textAnchor="end" fill="var(--muted)" fontSize={11}>
          Time between eruptions (min.)
        </text>
        {bins.map((bin) => {
          const proportion = bin.length / data.length;
          const left = x(bin.x0 ?? lo);
          const barWidth = Math.max(0, x(bin.x1 ?? lo) - left - 1);
          return (
            <rect
              key={bin.x0}
              x={left}
              y={y(proportion)}
              width={barWidth}
              height={innerHeight - y(proportion)}
              fill={BAR_FILL}
            />
          );
        })}
        {curves.map((curve) => (
          <path
            key={curve.bandwidth}
            d={line(curve.points) ?? ''}
            fill="none"
            stroke={color(String(curve.bandwidth))}
            strokeWidth={1.8}
            strokeLinejoin="round"
            strokeLinecap="round"
          />
        ))}
        <g transform={`translate(${innerWidth - 104},4)`}>
          {curves.map((curve, i) => (
            <g key={curve.bandwidth} transform={`translate(0,${i * 16})`}>
              <line x1={0} x2={22} y1={0} y2={0} stroke={color(String(curve.bandwidth))} strokeWidth={2} />
              <text x={28} dy="0.32em" fill="var(--text)" fontSize={11}>
                {`bandwidth ${curve.bandwidth}`}
              </text>
            </g>
          ))}
        </g>
      </g>
    </svg>
  );
}
